import{_ as t,o as r,c as e,a2 as i}from"./chunks/framework.z3u3TMv0.js";const u=JSON.parse('{"title":"隐私协议","description":"MiniTavern Ultra 隐私说明：对话、角色与 API 密钥等优先保存在本机；完整隐私政策见官方页面。","frontmatter":{"title":"隐私协议","description":"MiniTavern Ultra 隐私说明：对话、角色与 API 密钥等优先保存在本机；完整隐私政策见官方页面。","head":[["meta",{"property":"og:title","content":"隐私协议 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern Ultra 隐私说明：对话、角色与 API 密钥等优先保存在本机；完整隐私政策见官方页面。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/privacy"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/privacy"}]]},"headers":[],"relativePath":"privacy.md","filePath":"privacy.md","lastUpdated":1786329590000}'),n={name:"privacy.md"};function l(o,a,p,s,c,d){return r(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="隐私协议" tabindex="-1">隐私协议 <a class="header-anchor" href="#隐私协议" aria-label="Permalink to &quot;隐私协议&quot;">​</a></h1><p><strong>MiniTavern Ultra（超迷你酒馆）重视您的隐私。</strong> 本页概述数据如何处理；完整法律文本以官方隐私政策页面为准。</p><h2 id="本地优先" tabindex="-1">本地优先 <a class="header-anchor" href="#本地优先" aria-label="Permalink to &quot;本地优先&quot;">​</a></h2><p>在默认使用方式下，以下数据<strong>主要保存在您的设备中</strong>，不会作为聊天内容上传到 MiniTavern 自有业务服务器：</p><ul><li>对话历史记录</li><li>个性化设置与偏好</li><li>API 密钥信息（由您填写并保存在本机）</li><li>用户创建或导入的角色卡及相关配置</li><li>世界书、正则、人设等应用内配置</li></ul><p>备份文件（如 <code>.tbk</code>）由您自行导出与保管；请勿分享含密钥的备份。</p><h2 id="byok-与第三方" tabindex="-1">BYOK 与第三方 <a class="header-anchor" href="#byok-与第三方" aria-label="Permalink to &quot;BYOK 与第三方&quot;">​</a></h2><p>当您配置并调用第三方或本地模型服务时：</p><ul><li>请求会发往<strong>您指定的</strong> API 地址（云厂商或局域网中的 Ollama / LM Studio 等）</li><li>这些服务商会按其自身隐私政策处理请求内容</li><li>MiniTavern 无法代替第三方对您的提示词或生成结果负责</li></ul><h2 id="完整政策" tabindex="-1">完整政策 <a class="header-anchor" href="#完整政策" aria-label="Permalink to &quot;完整政策&quot;">​</a></h2><p>请阅读完整隐私政策：</p><p><strong><a href="https://minitavern.github.io/ultra_privacy/" target="_blank" rel="noreferrer">打开隐私协议全文</a></strong></p><p>如有疑问，请联系：<a href="mailto:minitavern@gmail.com" target="_blank" rel="noreferrer">minitavern@gmail.com</a></p><p>另见：<a href="/ultra_guides/terms">服务条款</a></p>',14)])])}const m=t(n,[["render",l]]);export{u as __pageData,m as default};
